package glitch

import data.glitch_lib

# Weak cryptographic algorithms
weak_symmetric := {"DES", "3DES", "TripleDES", "DESede", "Blowfish", "RC2", "RC4", "SKIPJACK", "TEA", "XTEA"}
weak_hashes := {"MD4", "MD5", "SHA0", "SHA1", "RIPEMD"}
weak_tls := {"SSL", "SSLv2", "SSLv3", "TLS1.0", "TLS1.1", "SSH1"}
weak_modes := {"ECB"}

# Cryptographic attribute names
crypto_attrs := {
    "encryption_algorithm", "encryption_type", "cipher", "cipher_suite",
    "kms_key_spec", "key_spec", "key_algorithm", "block_cipher_mode", 
    "mode_of_operation", "hash_algorithm", "digest_algorithm", "checksum_algorithm",
    "hmac_algorithm", "signing_algorithm", "signature_algorithm", "tls_version",
    "ssl_policy", "security_policy", "cipher_suite_policy", "preferred_ciphers",
    "allowed_ciphers", "key_length", "key_size", "modulus_length",
    "public_key_algorithm", "private_key_algorithm", "key_exchange",
    "diffie_hellman_group", "dh_group", "ecdh_curve", "algorithm"
}

# Warning keywords
warn_keywords := {"enable_legacy_crypto", "compatibility_mode", "legacy_mode", 
    "allow_weak_crypto", "permit_insecure", "custom_algorithm", "proprietary"}

check_weak_crypto(value) {
    value.ir_type == "String"
    alg := lower(value.value)
    combined := {lower(x) | x := weak_symmetric[_]} | {lower(x) | x := weak_hashes[_]} | {lower(x) | x := weak_tls[_]} | {lower(x) | x := weak_modes[_]}
    alg == combined[_]
}

check_weak_crypto(value) {
    value.ir_type == "String"
    alg := lower(value.value)
    contains(alg, lower(weak_symmetric[_]))
}

check_weak_crypto(value) {
    value.ir_type == "String"
    alg := lower(value.value)
    contains(alg, lower(weak_hashes[_]))
}

check_weak_crypto(value) {
    value.ir_type == "String"
    alg := lower(value.value)
    contains(alg, lower(weak_tls[_]))
}

check_weak_crypto(value) {
    value.ir_type == "String"
    alg := lower(value.value)
    contains(alg, lower(weak_modes[_]))
}

check_warning_flag(value) {
    value.ir_type == "Boolean"
    value.value == true
}

# Helper to recursively extract string values from complex structures
extract_strings(node) = strs {
    node.ir_type == "String"
    strs := {node.value}
} else = strs {
    node.ir_type == "Array"
    strs := {s | v := node.value[_]; s := extract_strings(v)[_]}
} else = strs {
    node.ir_type == "Hash"
    strs := {s | _, v := node.value; s := extract_strings(v)[_]}
} else = strs {
    node.ir_type == "VariableReference"
    strs := {node.value}
} else = strs {
    strs := set()
}

# Check for weak key sizes
check_weak_key_size(value) {
    value.ir_type == "Integer"
    value.value < 128
} else {
    value.ir_type == "String"
    to_number(value.value) < 128
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]
    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    # Check if attribute name matches crypto pattern
    attr_name_lower := lower(attr.name)
    {name_lower | name_lower := lower(crypto_attrs[_])}[attr_name_lower]

    check_weak_crypto(attr.value)

    result := {
        "type": "sec_weak_crypt",
        "element": attr,
        "path": parent.path,
        "description": "Use of a broken or risky cryptographic algorithm - Avoid using weak or deprecated cryptographic algorithms. (CWE-327)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]
    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    # Check warning flag attributes
    warn_lower := lower(attr.name)
    {w | w := lower(warn_keywords[_])}[warn_lower]

    check_warning_flag(attr.value)

    result := {
        "type": "sec_weak_crypt",
        "element": attr,
        "path": parent.path,
        "description": "Use of a broken or risky cryptographic algorithm - Avoid enabling legacy or weak cryptographic modes. (CWE-327)"
    }
}

